def transform_v2(grid):
    """Mark between markers in each row. Marker = non-background cell."""
    h, w = len(grid), len(grid[0])

    # Find background from edges
    from collections import Counter
    edge_colors = []
    for row in grid:
        if row:
            edge_colors.extend([row[0], row[-1]])
    for c in range(w):
        edge_colors.extend([grid[0][c], grid[h-1][c]])
    counter = Counter(edge_colors)
    background = counter.most_common(1)[0][0]

    # Find marker (non-background in interior)
    marker = None
    for r in range(1, h-1):
        for c in range(1, w-1):
            if grid[r][c] != background:
                marker = grid[r][c]
                break
        if marker:
            break
    if not marker and h > 1 and w > 1:
        for r in range(min(h, 5)):
            marker = grid[r][0]
            if marker != background:
                break

    result = [list(row) for row in grid]

    for r in range(h):
        row = result[r]
        markers = [c for c in range(w) if row[c] == marker]

        if not markers:
            continue

        if len(markers) == 1:
            # Single marker at c: color c with 2
            result[r][markers[0]] = 2
        else:
            # Multiple markers: color between first+1 and last-1 with 2
            first = markers[0]
            last = markers[-1]
            for c in range(first + 1, last):
                if row[c] == background:
                    row[c] = 2

    return result

